Arguments: {"code":"const tabId = 1962625075;

const products = await browserjs(tabId, () => {
  // Let's find the grid or cards containing the products
  // Each card likely has a link to the product page
  // Let's find all links whose href contains backcountry.com/ and doesn't contain /cat/, /rc/, /search
  const allLinks = Array.from(document.querySelectorAll('a[href]'));
  const productCards = [];

  for (const a of allLinks) {
    const href = a.href;
    // Check if it looks like a product URL (e.g. backcountry.com/<brand-product-slug>)
    if (/https:\/\/www\.backcountry\.com\/[a-z0-9-]+$/i.test(href) && 
        !href.includes('/cat/') && !href.includes('/rc/') && !href.includes('/search') &&
        !href.includes('summit-club') && !href.includes('about') && !href.includes('accessibility')) {

      // Let's get the container card
      const card = a.closest('[class*="card" i], [class*="product" i], [class*="css-"]') || a;
      // Extract text content
      const text = a.textContent.trim().replace(/\s+/g, ' ');
      if (text.length > 5 && /\$/.test(text)) {
        productCards.push({
          href,
          text,
          fullCardText: card.textContent.trim().replace(/\s+/g, ' ')
        });
      }
    }
  }

  // Deduplicate by href
  const uniqueCards = [];
  const seenHrefs = new Set();
  for (const item of productCards) {
    if (!seenHrefs.has(item.href)) {
      seenHrefs.add(item.href);
      uniqueCards.push(item);
    }
  }

  return {
    count: uniqueCards.length,
    sample: uniqueCards.slice(0, 10)
  };
});

